public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns suggested name for saving a file in a given directory
    /// </summary>
    public Task<TdLib.TdApi.Objects.Text> GetSuggestedFileNameAsync(int fileId = default, string directory = default)
    {

           using var activity =  StartCallActivity("GetSuggestedFileNameAsync", typeof(GetSuggestedFileName).FullName ?? "GetSuggestedFileNameAsync");

           try
           {
             return client.GetSuggestedFileNameAsync(fileId, directory);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
